-- billable rates: ASSUMED entirely (open in the reverse notes). user_id NULL = workspace default; list_id NULL = any list.
CREATE TABLE billable_rates (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid /* id -> identity.users */,
  list_id uuid /* id -> hierarchy.lists */,
  rate_cents bigint NOT NULL CHECK (rate_cents >= 0),
  currency char(3) NOT NULL,
  effective_from date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

-- resolve the rate for (user, list, date): most specific then latest effective_from.
CREATE INDEX billable_rates_lookup ON billable_rates (workspace_id, user_id, list_id, effective_from DESC);

CREATE TABLE time_off (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  from_date date NOT NULL, to_date date NOT NULL,
  kind text NOT NULL DEFAULT 'leave', status text NOT NULL DEFAULT 'approved' CHECK (status IN ('requested','approved','rejected')),
  half_day boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  CHECK (to_date >= from_date)
);

CREATE INDEX time_off_user ON time_off (workspace_id, user_id, from_date, to_date);
